import app from 'flarum/common/app';
import Link from 'flarum/common/components/Link';
import humanTime from 'flarum/common/utils/humanTime';
import Widget from '../../../forum-widgets-core/common/components/Widget';

/** Kartta gösterilecek üye sayısı */
const LIMIT = 5;
export function membersPageUrl() {
  try {
    return app.routes && app.routes['fof_user_directory'] ? app.route('fof_user_directory', {
      sort: 'newest'
    }) : null;
  } catch (e) {
    return null;
  }
}
export function memberRows(members, limit, onClick) {
  return members.slice(0, limit).map(u => m(Link, {
    href: app.route('user', {
      username: u.username
    }),
    className: "FStats-member",
    key: u.id,
    onclick: onClick
  }, u.avatar ? m("img", {
    className: "FStats-member-avatar",
    src: u.avatar,
    alt: "",
    loading: "lazy"
  }) : m("span", {
    className: "FStats-member-avatar is-letter"
  }, (u.displayName || '?').charAt(0).toLocaleUpperCase('tr-TR')), m("span", {
    className: "FStats-member-body"
  }, m("span", {
    className: "FStats-member-name"
  }, u.displayName), m("span", {
    className: "FStats-member-sub"
  }, m("i", {
    className: "fas fa-user-plus",
    "aria-hidden": "true"
  }), " ", u.joinedAt ? [humanTime(new Date(u.joinedAt)), ' katıldı'] : 'Yeni üye'))));
}

/**
 * Yeni Üyeler kartı: aramıza son katılanlar (Çevrimiçi kartıyla aynı tasarım dili).
 * Veri forum istatistikleriyle birlikte gelir (izin: framio-stats.view.latestMember).
 */
export default class NewMembersWidget extends Widget {
  className() {
    return 'Framio-NewMembersWidget';
  }
  icon() {
    return 'fas fa-user-plus';
  }
  title() {
    return 'Aramıza katılanlar';
  }
  description() {
    return '';
  }
  content() {
    const s = app.forum.attribute('framioStats') || {};
    const members = s.newMembers || [];
    if (!members.length) return m("div", {
      className: "FStats-members-empty"
    }, "Hen\xFCz yeni \xFCye yok.");
    const more = membersPageUrl();
    return m("div", {
      className: "FStats-members"
    }, m("div", {
      className: "FStats-members-list"
    }, memberRows(members, LIMIT)), more ? m(Link, {
      href: more,
      className: "FStats-more"
    }, m("span", null, "T\xFCm \xFCyeler"), m("i", {
      className: "fas fa-arrow-right",
      "aria-hidden": "true"
    })) : null);
  }
}
flarum.reg.add('framio-widgets', 'forum-statistics-widget/common/components/NewMembersWidget', NewMembersWidget);